import subprocess, sys, json, itertools

opts = [l.strip() for l in open('/tmp/cv/cmdlist.txt') if l.strip()]
SKIP = {'-distribute-cache', '+distribute-cache', '-help', '+help', '-version', '+version', '-list', '+list',
        '-display', '+display', '-remote', '+remote'}
dummies = ["1", "10x10", "red", "Over", "Add", "SRT", "none", "0.5", "Undefined", "foo", "Rgb", "Dilate", "Diamond", "Bilinear"]

def run(args):
    try:
        p = subprocess.run(['convert', 'xc:red'] + args, capture_output=True, text=True, timeout=10, cwd='/tmp/cv/sandbox')
    except subprocess.TimeoutExpired:
        return 'TIMEOUT', ''
    err = p.stderr
    if 'unrecognized option' in err: return 'UNREC', err
    if 'missing argument' in err: return 'MISSING_ARG', err
    if 'missing an image filename' in err: return 'OK', err
    if p.returncode == 0: return 'OK0', err
    return 'OTHER', err.strip().splitlines()[0] if err.strip() else ''

result = {}
for o in opts:
    if o in SKIP:
        result[o] = 'SKIPPED'; continue
    st, err = run([o])
    if st == 'UNREC':
        result[o] = 'UNREC'; continue
    if st in ('OK', 'OK0'):
        result[o] = 0; continue
    found = None
    notes = []
    for n in (1, 2, 3):
        combos = [[d]*n for d in dummies]
        if n == 2:
            combos += [list(c) for c in itertools.product(dummies, repeat=2)]
        statuses = set()
        for c in combos:
            st, err = run([o] + c)
            statuses.add(st)
            if st in ('OK', 'OK0'):
                found = n; break
            if st == 'OTHER': notes.append(err)
        if found is not None: break
        if 'MISSING_ARG' not in statuses:
            # all consumed but validation failed; assume n args
            found = f'{n}?'
            break
    result[o] = found if found is not None else ('?', notes[:3])
json.dump(result, open('/tmp/cv/probe.json', 'w'), indent=1)
for k, v in result.items():
    print(k, v)

